import{_ as o,l as i,o as e,c as l,v as t,p as n,x as s,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"偏序与格直觉","description":"","frontmatter":{"title":"偏序与格直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/poset-lattice.md","filePath":"cs/poset-lattice.md","lastUpdated":1789023840000}'),h={name:"cs/poset-lattice.md"};function E(A,a,B,m,_,u){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="偏序与格直觉" tabindex="-1">偏序与格直觉 <a class="header-anchor" href="#偏序与格直觉" aria-label="Permalink to &quot;偏序与格直觉&quot;">​</a></h1><div class="epigraph"><p>可比才谈大小，不可比则并排；若任意两个元都有最小上界与最大下界，这张序就是格。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/equivalence-partition">等价关系与划分</a>钉死了对称的「同一类」。本课不重证划分对应，也不从「序数」另起。缺口是：后课 DAG、包含、布尔代数的 \\(x\\le y\\)，要的是<strong>反对称</strong>的比较，不是对称的可替换。集合课点过偏序，没有 Hasse、没有交并当运算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>等价把互相到达的元粘成一点。序要保留方向：\\(x\\le y\\) 且 \\(y\\le x\\) 则 \\(x=y\\)。缺口因此不是再造有序对，而是：自反、反对称、传递的关系叫做偏序；未必全序——可以有不可比的元。Hasse 图去掉自反与可传递推得的边，只留覆盖关系。</p><p>若任意 \\(x,y\\) 都有上确界 \\(x\\vee y\\) 与下确界 \\(x\\wedge y\\)，偏序集是<strong>格</strong>。幂集用 \\(\\subseteq\\)，交并就是确界：这把<a href="/cs/boolean-algebra">布尔代数</a>解释成某集合的幂集格，本课只要这个对照，不把门电路请回来。</p><h3 id="偏序不是拓扑排序本身" tabindex="-1">偏序不是拓扑排序本身 <a class="header-anchor" href="#偏序不是拓扑排序本身" aria-label="Permalink to &quot;偏序不是拓扑排序本身&quot;">​</a></h3><p>拓扑序是把偏序<strong>扩展</strong>成全序（若无环）。本课对象还没有「图上的边当序」；那是 DAG 课。把 Hasse 当成算法流程图，后课会把覆盖与可达混名。</p><p><span class="marginnote">Rosen 用整除偏序与幂集格当主例。整除：\\(\\mathrm{lcm}\\) 与 \\(\\gcd\\) 是并与交。布尔格的互补律对应上一课程的 \\(\\bar x\\)。函数与可数下一课才要单射满射。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检查三性质。画 Hasse：底小顶大（或反过来，声明即可）。求两元的公共上界中的最小者；不存在则不是格（例如缺了某并）。全序是任意两元可比的偏序。</p>',11)),(e(),n(c,null,{default:s(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EQ%5B%22%E7%AD%89%E4%BB%B7%EF%BC%9A%E5%AF%B9%E7%A7%B0%22%5D%20--%3E%20PO%5B%22%E5%81%8F%E5%BA%8F%EF%BC%9A%E5%8F%8D%E5%AF%B9%E7%A7%B0%22%5D%0A%20%20PO%20--%3E%20HASSE%5B%22Hasse%20%E8%A6%86%E7%9B%96%22%5D%0A%20%20PO%20--%3E%20LAT%5B%22%E6%A0%BC%EF%BC%9A%E4%BB%BB%E6%84%8F%E4%B8%A4%E5%85%83%E6%9C%89%E4%BA%A4%E5%B9%B6%22%5D%0A%20%20LAT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%87%BD%E6%95%B0%E4%B8%8E%E5%8F%AF%E6%95%B0%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课类型包含、文件系统目录（若当包含则要小心循环挂载）、知识树本身，都是偏序直觉。格给「最小公共超类型 / 最大公共子类型」一句话：那是 \\(\\vee\\)/\\(\\wedge\\)。本课不把格论定理（模格、分配格分类）写进主干；分配性已在布尔公理里用过。</p><p>划分的细化按「更细」构成偏序，上一课末句留下的缺口在这里落地：等价关系按包含也成偏序，一般不是全序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入良基关系上的超限归纳——归纳下一课才从 \\(\\mathbb{N}\\) 开始。也不把偏函数、单调函数当重点；函数作为右唯一关系是下一课。电路时序的状态图是有向图，未必是偏序（有环就不是）。</p><p>后课默认：谈到 \\(\\le\\)、包含、整除，先问是否偏序、是否格。编号与双射另说。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>偏序是自反、反对称、传递；允许不可比。</li><li>格要求任意两元有上、下确界；幂集是标准例子。</li><li>下一课把关系收成函数，并谈可数。</li><li>出处：Rosen, <em>Discrete Mathematics and Its Applications</em>。</li></ul>',8))])}const x=o(h,[["render",E]]);export{b as __pageData,x as default};
